Q: JWT C++ OpenSSL RS256 Signature Verification A: <p>After putting Topaco's solution into practice, I went back for completion's sake and also fixed the byte order issue in the question's original code by using <a href="https://stackoverflow.com/a/4181991/7431860">this answer's solution</a> to check whether the machine is big- or little-endian, and then reordered the byte streams if necessary:</p>
<pre class="lang-cpp prettyprint-override"><code>  //---- create a public key object -------------------------------------------
  //load the exponent and modulus into memory 
  std::string rsa_e = base64_decode(e_base64_url);
  std::string rsa_n = base64_decode(n_base64_url);

  int is_little_endian = 1;
  if(*(char *)&amp;is_little_endian == 1) {
    //this is a little-endian machine, need to flip these big-endian values
    std::reverse(rsa_n.begin(), rsa_n.end());
    std::reverse(rsa_e.begin(), rsa_e.end());
  }

  OSSL_PARAM params[3];
  params[0] = OSSL_PARAM_construct_BN(&quot;n&quot;, (unsigned char *)rsa_n.data(), rsa_n.size());
  params[1] = OSSL_PARAM_construct_BN(&quot;e&quot;, (unsigned char *)rsa_e.data(), rsa_e.size());
  params[2] = OSSL_PARAM_construct_end();

  EVP_PKEY_CTX *pkctx = EVP_PKEY_CTX_new_from_name(NULL, &quot;RSA&quot;, NULL);
  EVP_PKEY *pkey = NULL;

  if(
        pkctx == NULL
    ||  EVP_PKEY_fromdata_init(pkctx) &lt;= 0
    ||  EVP_PKEY_fromdata(pkctx, &amp;pkey, EVP_PKEY_PUBLIC_KEY, params) &lt;= 0
  ) {
    std::cerr &lt;&lt; &quot;private key setup failure&quot; &lt;&lt; std::endl;
    return -1;
  }
</code></pre>
